CREATE TABLE IF NOT EXISTS `web_offline_track` (`id` VARCHAR(40) NOT NULL, `type` INT NULL, `type_extra` BIGINT NULL, `track_id` BIGINT NULL, `detail` TEXT NULL, `size` INT NULL, `dfsid` BIGINT NULL, `bitrate` INT NULL, `state` INT NULL, `download_time` INT NULL, `complete_time` INT NULL, `source_href` TEXT NULL, `source_text` TEXT NULL, `source_extra` TEXT NULL, `album_id` VARCHAR(40) NULL, `relative_path` TEXT NULL, `track_name` TEXT NULL, `artist_name` TEXT NULL, `album_name` TEXT NULL, `id3_state` INT DEFAULT 0, PRIMARY KEY (`id`)); CREATE INDEX IF NOT EXISTS `index_track_name` ON `web_offline_track` (`track_name` ASC); CREATE INDEX IF NOT EXISTS `index_artist_name` ON `web_offline_track` (`artist_name` ASC); CREATE INDEX IF NOT EXISTS `index_album_name` ON `web_offline_track` (`album_name` ASC); CREATE INDEX IF NOT EXISTS `index_size` ON `web_offline_track` (`size` ASC); CREATE INDEX IF NOT EXISTS `index_download_time` ON `web_offline_track` (`download_time` ASC); CREATE INDEX IF NOT EXISTS `index_complete_time` ON `web_offline_track` (`complete_time` ASC);
CREATE TABLE IF NOT EXISTS `web_playlist_order` (`playlist_id` BIGINT NOT NULL, `field` VARCHAR(40) NULL, `order` VARCHAR(40) NULL, PRIMARY KEY (`playlist_id`));
CREATE TABLE IF NOT EXISTS `web_map` (`key` TEXT NOT NULL, `value` TEXT NULL, PRIMARY KEY (`key`));
CREATE TABLE IF NOT EXISTS `web_track` (`tid` INTERGER NOT NULL, `version` INTERGER NOT NULL DEFAULT 0, `track` TEXT NOT NULL DEFAULT "", PRIMARY KEY (`tid`));
CREATE TABLE IF NOT EXISTS `web_playlist_track` (`pid` INTERGER NOT NULL DEFAULT 0, `tid` INTERGER NOT NULL DEFAULT 0, `version` INTERGER NOT NULL DEFAULT 1, `order` INTERGER NOT NULL DEFAULT 0);CREATE INDEX IF NOT EXISTS `index_order` ON `web_playlist_track` (`order` ASC);
CREATE TABLE IF NOT EXISTS `web_playlist` (`pid` INTERGER NOT NULL, `playlist` TEXT NOT NULL DEFAULT "", PRIMARY KEY (`pid`));
CREATE TABLE IF NOT EXISTS `web_user_playlist` (`uid` INTERGER NOT NULL, `pids` TEXT NOT NULL DEFAULT "", PRIMARY KEY (`uid`));
CREATE TABLE IF NOT EXISTS `web_cloud_track` (`uid` INTERGER NOT NULL DEFAULT 0, `id` VARCHAR(40) NOT NULL DEFAULT "", `fileId` VARCHAR(40) NOT NULL DEFAULT "", `file` TEXT NOT NULL DEFAULT "", `fileExt` TEXT NOT NULL DEFAULT "", `size` INTERGER NOT NULL DEFAULT 0, `bitrate` INTERGER NOT NULL DEFAULT 0, `time` INTERGER NOT NULL DEFAULT 0, `name` TEXT NOT NULL DEFAULT "", `album` TEXT NOT NULL DEFAULT "", `artist` TEXT NOT NULL DEFAULT "", `track` TEXT NOT NULL DEFAULT "", `state` INTERGER NOT NULL DEFAULT 0, `version` INTERGER NOT NULL DEFAULT 0, `mst` INTERGER NOT NULL DEFAULT 0, `cueFile` TEXT NOT NULL DEFAULT "", `offset` INTERGER NOT NULL DEFAULT 0, `duration` INTERGER NOT NULL DEFAULT 0, PRIMARY KEY (`uid`, `id`)); CREATE INDEX IF NOT EXISTS `index_name` ON `web_cloud_track` (`name` ASC); CREATE INDEX IF NOT EXISTS `index_album` ON `web_cloud_track` (`album` ASC); CREATE INDEX IF NOT EXISTS `index_artist` ON `web_cloud_track` (`artist` ASC); CREATE INDEX IF NOT EXISTS `index_fileExt` ON `web_cloud_track` (`fileExt` ASC); CREATE INDEX IF NOT EXISTS `index_size` ON `web_cloud_track` (`size` ASC); CREATE INDEX IF NOT EXISTS `index_time` ON `web_cloud_track` (`time` ASC);